  const nextExpected = last.posted + typical * DAY;
  // Gone quiet for well over a cycle: probably cancelled.
  if (now > nextExpected + Math.max(7, typical * 0.5) * DAY) return null;

  const previous = runs.length === 2 ? runs[0].at(-1)  : null;
