    id,
    name: last.t.payee,
    category: last.t.category,
    accountName: last.t.accountName.replace(/\s*\(\d+\)$/, ""),
    cadence: match.cadence,
    amount: last.amount,
    previousAmount: previous !== null && last.amount > previous ? previous : null,
    lastCharged: last.posted,
    nextExpected,
